  if candidate.exists():
   r=json.loads(candidate.read_text());sources=dict(id=site,construction=candidate.relative_to(ROOT).as_posix(),layout=r['layout'],glb=candidate.with_name('cut-terrain.glb').relative_to(ROOT).as_posix(),native=candidate.with_name('cut-terrain.hcs2').relative_to(ROOT).as_posix(),blend=candidate.with_name('cut-terrain.blend').relative_to(ROOT).as_posix(),glb_sha256=r['glb_sha256'],native_sha256=r['physics_sha256']);decision='SAVED_TERRAIN_AND_ROOTED_CIRCULATION_SOURCE_REVISED'
  else:
   sources=row;decision='SAVED_WORLD_AUTHORED_MAP_COMPOSITE_PENDING' if (OUT/(site.lower()+'-world.json')).exists() else proposal['decision']
