 write(OUT/'roster.json',dict(status='BROAD_SAVED_CIRCULATION_TERRAIN_SOURCE_PASS_IN_PROGRESS_NOT_MAP_ACCEPTANCE',sites=rows,active_sources=active,evidence=args.evidence.as_posix(),aggregate=aggregate));write(v/'aggregate.json',aggregate)
 print('TERRAIN_CHECKPOINT',len(rows),'packets;',aggregate['revised_native_sources'],'composites;',aggregate['saved_editor_worlds'],'saved worlds;',len(aggregate['tested_sites']),'tested sites',flush=True)
